#include "Gui/Views/GuiHost.hpp"

#include <QFont>
#include <QFontDatabase>
#include <QGuiApplication>
#include <QQmlComponent>
#include <QQmlEngine>
#include <QQmlProperty>
#include <QQuickWindow>
#include <stdexcept>

#include "Gui/ViewModels/MaximalGuiViewModel.hpp"
#include "Gui/ViewModels/MinimalGuiViewModel.hpp"

// Generated by qt_add_qml_module for the plugin-less Sarwave.Gui module.
void qml_register_types_Sarwave_Gui();

namespace Sarwave::Core::Gui::Views {
namespace {

/// Marks the items placed by show*Gui, so the next call knows what it replaces.
constexpr const char* ContentMarker = "sarwaveGuiContent";

QQuickItem* show(QQuickWindow& window, QQmlEngine& engine, const char* typeName,
                 QObject* viewModel) {
    initialize();

    QQmlComponent component(&engine);
    component.loadFromModule("Sarwave.Gui", typeName);
    if (component.isError()) {
        delete viewModel;
        throw std::runtime_error("Failed to load " + std::string(typeName) + ": " +
                                 component.errorString().toStdString());
    }

    QObject* created =
        component.createWithInitialProperties({{"viewModel", QVariant::fromValue(viewModel)}});
    auto* item = qobject_cast<QQuickItem*>(created);
    if (!item) {
        delete created;
        delete viewModel;
        throw std::runtime_error(std::string(typeName) +
                                 " is not an item: " + component.errorString().toStdString());
    }
    viewModel->setParent(item);  // the view model lives and dies with its view

    // Replace whatever the window showed: earlier dashboards are deleted, anything else (the
    // window's own QML content) is hidden.
    QQuickItem* content = window.contentItem();
    for (QQuickItem* child : content->childItems()) {
        if (child->property(ContentMarker).toBool()) {
            child->setParentItem(nullptr);
            child->deleteLater();
        } else {
            child->setVisible(false);
        }
    }

    item->setProperty(ContentMarker, true);
    item->setParent(content);
    item->setParentItem(content);
    QQmlProperty(item, QStringLiteral("anchors.fill")).write(QVariant::fromValue(content));
    return item;
}

}  // namespace

void initialize() {
    static const bool done = [] {
        for (const char* file :
             {"Inter-Regular.ttf", "Inter-Medium.ttf", "Inter-SemiBold.ttf", "Inter-Bold.ttf",
              "Inter-Light.ttf", "Inter-Thin.ttf", "CascadiaMono.ttf"}) {
            QFontDatabase::addApplicationFont(QStringLiteral(":/Sarwave/Gui/Fonts/") +
                                              QString::fromLatin1(file));
        }
        QFont font(QStringLiteral("Inter"));
        font.setPixelSize(14);
        QGuiApplication::setFont(font);

        qml_register_types_Sarwave_Gui();
        return true;
    }();
    (void)done;
}

QQuickItem* showMaximalGui(QQuickWindow& window, QQmlEngine& engine, Models::RadarData& data) {
    return show(window, engine, "MaximalGui", new ViewModels::MaximalGuiViewModel(data));
}

QQuickItem* showMinimalGui(QQuickWindow& window, QQmlEngine& engine, Models::RadarData& data) {
    return show(window, engine, "MinimalGui", new ViewModels::MinimalGuiViewModel(data));
}

QQuickItem* showMaximalGuiDesign(QQuickWindow& window, QQmlEngine& engine) {
    return show(window, engine, "MaximalGui",
                new ViewModels::MaximalGuiViewModel(ViewModels::DesignMode));
}

QQuickItem* showMinimalGuiDesign(QQuickWindow& window, QQmlEngine& engine) {
    return show(window, engine, "MinimalGui",
                new ViewModels::MinimalGuiViewModel(ViewModels::DesignMode));
}

}  // namespace Sarwave::Core::Gui::Views
